fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    let mut left = 0;
    let mut right = arr.len();
    let mut result = None;
    
    while left < right {
        let mid = left + (right - left) / 2;
        
        if arr[mid] < target {
            left = mid + 1;
        } else if arr[mid] > target {
            right = mid;
        } else {
            // Found target, but need to check if there's an earlier occurrence
            result = Some(mid);
            // Continue searching in the left half
            right = mid;
        }
    }
    
    result
}